const input=document.getElementById('service-query');const cards=[...document.querySelectorAll('.directory-link')];const clean=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();function update(){const q=clean(input.value.trim());let count=0;cards.forEach(c=>{const show=clean(c.textContent+' '+c.dataset.serviceSearch).includes(q);c.hidden=!show;if(show)count++;});document.getElementById('service-query-status').textContent=count?count+' nhóm dịch vụ phù hợp':'Chưa tìm thấy. Thử tên dịch vụ hoặc từ khóa ngắn hơn.';}input.addEventListener('input',update);document.querySelectorAll('[data-find]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.find;update();}));update();
